  "dataModelSchema": {
    "card": {
      "title": {
        "type": "string",
        "description": "半马目标倒计时的短展示文案。",
        "sampleValue": "距半马12天"
      }
    },
    "meter": {
      "progressValue": {
        "type": "number",
        "description": "本周运动完成度的进度值。",
        "sampleValue": 80
      },
