        "sampleValue": 100
      },
      "centerLabel": {
        "type": "string",
        "description": "环形进度中间的短标签，说明进度范围。",
        "sampleValue": "本周"
      },
      "caption": {
        "type": "string",
        "description": "完成状态的短标签。",
        "sampleValue": "已达成"
      }
    },
    "support": {
      "line1": {
        "type": "string",
        "description": "本周运动完成度的百分比展示文本。",
        "sampleValue": "80%"
      },
      "line2": {
        "type": "string",
        "description": "正向运动状态短说明。",
        "sampleValue": "状态良好"
      }
    },
    "action": {
      "label": {
        "type": "string",
        "description": "跳转运动健康应用的入口文案。",
        "sampleValue": "运动健康"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_run.png",
      "description": "运动/跑步图标，适合用于运动健身卡片的识别入口或目标提示。"
    },
    {
      "src": "resources/base/media/icon_like.png",
      "description": "心形图标，适合用于运动健康、心率监测或健康应用入口。"
    }
  ]
}

